// ===================== QUIZ DATA =====================
const qzData=[{"q":"Según Tom Wolfe, «The New Journalism» (1973), ¿qué autoriza el Nuevo Periodismo?","o":["a) Usar las técnicas de la ficción (escena, diálogo completo, punto de vista, detalle de estatus) sobre hechos reales, sin fabricar nada","b) Inventar diálogos que suenen mejor","c) Cambiar los hechos si mejoran la historia","d) No citar nunca las fuentes"],"c":0,"e":"Wolfe defiende llevar las técnicas de la ficción al reportaje, con la regla de que todo tiene que ser real: usar la técnica es lícito, inventar el hecho no."},{"q":"¿Qué cuestionamiento pesa sobre «A sangre fría» de Truman Capote (1966)?","o":["a) Que investigaciones posteriores han cuestionado la exactitud de algunas escenas, en especial el cierre en el cementerio","b) Que Capote nunca viajó a Kansas","c) Que el libro es una novela de ficción declarada","d) Que el caso de los asesinatos fue inventado por completo"],"c":0,"e":"Es una duda documentada sobre algunas escenas, no una sentencia de que Capote mintió en todo el libro."},{"q":"Según Philippe Lejeune, «El pacto autobiográfico» (1975), ¿qué es el pacto con el lector?","o":["a) La promesa de que la no ficción firma con el lector: esto ocurrió de verdad, distinto del pacto de la ficción","b) Un contrato legal entre autor y editorial","c) Un acuerdo sobre el precio del libro","d) La regla de nunca usar diálogo"],"c":0,"e":"El pacto autobiográfico: la no ficción promete al lector que lo contado ocurrió de verdad; romperlo sin avisar es la falta de fondo."},{"q":"Según Janet Malcolm, «El periodista y el asesino» (1990), ¿qué deuda tiene el periodista?","o":["a) Ninguna, la historia le pertenece por completo","b) Una deuda ética con la persona real, porque se ganó su confianza para después contar la historia a su manera","c) Una deuda económica con el entrevistado","d) La deuda de publicar solo lo que el entrevistado autorice"],"c":1,"e":"Malcolm sostiene que el periodista se gana la confianza del sujeto para contar la historia a su manera, y eso crea una deuda ética real."},{"q":"¿Qué pasó con «Jimmy's World», de Janet Cooke, The Washington Post (1980-1981)?","o":["a) Ganó el Pulitzer en 1981 y se confirmó como reportaje verídico","b) Nunca se publicó por falta de pruebas","c) Fue un reportaje declarado como ficción desde el inicio","d) Ganó el Pulitzer en 1981 y tuvo que devolverse días después, porque Jimmy no existía"],"c":3,"e":"Cooke inventó a Jimmy, ganó el Pulitzer en 1981 y lo devolvió días después al descubrirse que el niño no existía: fijó la norma del compuesto declarado."},{"q":"¿Por qué no sostuvo James Frey su defensa de la «verdad emocional» en «A Million Little Pieces» (2003, destapado en 2006)?","o":["a) Porque nunca la usó como defensa","b) Porque el libro se vendió como novela desde el principio","c) Porque si algo se vende como memorias reales, tiene que haber ocurrido, y gran parte del libro estaba fabricado","d) Porque la editorial lo obligó a inventar"],"c":2,"e":"Frey vendió como memorias un relato en gran parte inventado; «verdad emocional» no sostiene el pacto si se vende como ocurrido."},{"q":"Según Johnson, Hashtroudi y Lindsay, «Source monitoring» (1993), ¿qué error puede cometer hasta el escritor honrado?","o":["a) Escribir demasiado rápido","b) Olvidar el título de sus fuentes","c) Confundir si algo lo vivió, lo imaginó o se lo contaron","d) Citar demasiadas fuentes"],"c":2,"e":"El monitoreo de la fuente: la mente a veces confunde el origen de un recuerdo, si fue vivido, imaginado o contado."},{"q":"Según Garry, Manning, Loftus y Sherman (1996), ¿qué hace la inflación por imaginación?","o":["a) Reduce la confianza en los recuerdos falsos","b) Sube la confianza de que un suceso ocurrió, solo por haberlo imaginado","c) Solo afecta a los niños","d) Prueba que todo recuerdo imaginado es falso"],"c":1,"e":"Imaginar un suceso sube la confianza de que ocurrió de verdad; por eso «lo recuerdo así» no es prueba suficiente en no ficción."},{"q":"¿Cuáles son las tres casillas de la ficha de la no ficción, la herramienta de esta etapa?","o":["a) Título, música y duración","b) Gancho, giro y cierre","c) Presupuesto, elenco y locación","d) ¿Ocurrió y cómo lo sé?, ¿qué reordené y qué no inventé?, ¿tengo el permiso y respeté al que aparece?"],"c":3,"e":"La ficha de la no ficción: si ocurrió y cómo se sabe, qué se reordenó sin inventar, y si hay permiso y respeto por quien aparece."},{"q":"¿Cuál es la diferencia entre reordenar e inventar, la grieta de esta etapa?","o":["a) No hay ninguna diferencia real","b) Reordenar (seleccionar, comprimir, ordenar hechos reales) es oficio lícito; inventar (fabricar una escena, cita o persona) es otra cosa","c) Inventar siempre es más honesto que reordenar","d) Reordenar solo se permite en la ficción"],"c":1,"e":"Reordenar hechos reales es oficio; inventar hechos que no ocurrieron es otra cosa, con otro nombre, y no es lícito en no ficción."}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
function showQz(){if(qzIdx>=qzData.length){document.getElementById('qzQ').textContent='🎉 ¡Quiz completado!';document.getElementById('qzOpts').innerHTML='';fin('s-quiz');unlockAchievement('primer_quiz');return;}const q=qzData[qzIdx];document.getElementById('qzProg').textContent=`Pregunta ${qzIdx+1} de ${qzData.length}`;document.getElementById('qzQ').textContent=q.q;const opts=document.getElementById('qzOpts');opts.innerHTML='';q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(qzDone)return;document.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');qzSel=i;sfx('click');};opts.appendChild(b);});qzDone=false;}
function checkQz(){if(qzSel<0)return fb('fbQz','Selecciona una respuesta.',false);qzDone=true;const opts=document.querySelectorAll('.qz-opt');if(qzSel===qzData[qzIdx].c){opts[qzSel].classList.add('correct');fb('fbQz','¡Correcto! +5 XP',true);if(!xpTracker.qz.has(qzIdx)){xpTracker.qz.add(qzIdx);pts(5);}sfx('ok');}else{opts[qzSel].classList.add('wrong');opts[qzData[qzIdx].c].classList.add('correct');fb('fbQz','Incorrecto. Revisa la respuesta correcta.',false);sfx('no');}setTimeout(()=>{qzIdx++;qzSel=-1;showQz();},1600);}
function resetQz(){sfx('click');qzIdx=0;qzSel=-1;qzDone=false;showQz();document.getElementById('fbQz').classList.remove('show');}

