const explainQuestions=[{"q":"Explica los cuatro recursos del Nuevo Periodismo, según Tom Wolfe, «The New Journalism» (1973), y por qué usarlos no autoriza a inventar.","ans":"Tom Wolfe, en «The New Journalism» (1973), describe cuatro recursos de la ficción llevados al reportaje: la escena por escena, en vez del resumen; el diálogo completo, registrado y no reconstruido de memoria; el punto de vista, contar desde adentro de alguien; y el detalle de estatus, el objeto o el gesto que revela una posición social. Wolfe insiste en que TODO tiene que ser real: usar estas técnicas sobre hechos comprobables es lícito, pero usarlas para disfrazar un hecho inventado no lo es. Su límite es que el propio movimiento tuvo abusos, así que la técnica, por sí sola, no garantiza que nadie la use mal."},{"q":"Explica qué es la novela de no ficción, según Truman Capote, «A sangre fría» (1966), y el cuestionamiento documentado sobre su exactitud.","ans":"Truman Capote, en «A sangre fría» (In Cold Blood, 1966), llevó las técnicas del Nuevo Periodismo a su extremo: reconstruyó un cuádruple asesinato real en Kansas con el detalle y la escena de una novela, y juró que cada palabra era verdad. Esa es la cumbre de la técnica. Pero investigaciones posteriores han cuestionado la exactitud de algunas escenas, en especial el cierre en el cementerio, y esa disputa sigue abierta. Es importante citarlo con cuidado: es una duda documentada sobre partes del libro, no una prueba de que Capote inventó todo, y se enseña como logro de la técnica y como aviso a la vez."},{"q":"Explica la ficha de la no ficción, la herramienta de esta etapa, y cómo se aplicaría al caso de Janet Cooke (1980-1981).","ans":"La ficha de la no ficción tiene tres casillas: ¿ocurrió, y cómo lo sé? (¿hay un testigo, un documento o un registro que lo sostenga?); ¿qué reordené, y qué NO inventé? (seleccionar, comprimir y ordenar es lícito, inventar una escena, una cita o una persona no lo es); y ¿tengo el permiso, y respeté al que aparece? Aplicada al caso de Janet Cooke, «Jimmy's World» (The Washington Post, 1980-1981): la primera casilla falla de raíz, porque Jimmy no existía y no había ningún testigo ni registro que sostuviera su historia; la segunda también falla, porque Cooke no reordenó hechos reales, inventó un personaje compuesto sin declararlo; y la tercera no aplica, porque no hay una persona real cuyo permiso se pudiera pedir. El caso fijó la norma: un compuesto se declara siempre."},{"q":"Explica la diferencia entre reordenar e inventar, y por qué la verdad emocional no sostuvo la defensa de James Frey (2006).","ans":"Reordenar es seleccionar, comprimir y ordenar hechos reales: decidir qué escena contar primero, cuánto tiempo resumir en un párrafo, o en qué orden presentar lo que de verdad ocurrió. Es oficio, y es lícito. Inventar es fabricar una escena, una cita o una persona que no existió: eso es otra cosa, y tiene otro nombre. James Frey vendió «A Million Little Pieces» (2003) como memorias reales, y cuando se destapó, en 2006, que gran parte del relato estaba fabricado, defendió que lo que importaba era la «verdad emocional» del libro. Esa defensa no sostuvo el pacto con el lector (Lejeune, 1975): si algo se vende como ocurrido, tiene que haber ocurrido; la verdad emocional puede acompañar a un relato real, pero no reemplaza la pregunta de si los hechos pasaron de verdad."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra la herramienta ilustrada en cada oración. Escribe al lado de qué herramienta se trata.',"<strong>Ejemplo:</strong> El caso del niño inventado que ganó y devolvió el Pulitzer. → <span style=\"color:var(--jade);font-weight:700;\">Jimmy's World (Cooke, 1980-1981)</span>"]);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y nota.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Nota')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Nota: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

// ===================== SOPA DE LETRAS =====================
const sopaSets=[{"size":10,"grid":[["W","O","L","F","E","X","Q","Z","T","R"],["C","A","P","O","T","E","M","N","B","J"],["L","E","J","E","U","N","E","W","D","S"],["M","A","L","C","O","L","M","X","Y","Z"],["C","O","O","K","E","B","F","N","T","R"],["F","R","E","Y","S","T","U","V","W","X"],["J","O","H","N","S","O","N","Q","R","T"],["L","O","F","T","U","S","A","B","C","D"],["R","E","O","R","D","E","N","A","R","X"],["I","N","V","E","N","T","A","R","Y","Z"]],"words":[{"w":"WOLFE","cells":[[0,0],[0,1],[0,2],[0,3],[0,4]]},{"w":"CAPOTE","cells":[[1,0],[1,1],[1,2],[1,3],[1,4],[1,5]]},{"w":"LEJEUNE","cells":[[2,0],[2,1],[2,2],[2,3],[2,4],[2,5],[2,6]]},{"w":"MALCOLM","cells":[[3,0],[3,1],[3,2],[3,3],[3,4],[3,5],[3,6]]},{"w":"COOKE","cells":[[4,0],[4,1],[4,2],[4,3],[4,4]]},{"w":"FREY","cells":[[5,0],[5,1],[5,2],[5,3]]},{"w":"JOHNSON","cells":[[6,0],[6,1],[6,2],[6,3],[6,4],[6,5],[6,6]]},{"w":"LOFTUS","cells":[[7,0],[7,1],[7,2],[7,3],[7,4],[7,5]]},{"w":"REORDENAR","cells":[[8,0],[8,1],[8,2],[8,3],[8,4],[8,5],[8,6],[8,7],[8,8]]},{"w":"INVENTAR","cells":[[9,0],[9,1],[9,2],[9,3],[9,4],[9,5],[9,6],[9,7]]}]}];
let currentSopaSetIdx=0,sopaFoundWords=new Set();
let sopaFirstClickCell=null,sopaPointerStartCell=null,sopaPointerMoved=false,sopaSelectedCells=[];
function getSopaCellSize(){const container=document.getElementById('sopaGrid');if(!container||!container.parentElement)return 28;const avail=container.parentElement.clientWidth-16;const set=sopaSets[currentSopaSetIdx];return Math.max(20,Math.min(32,Math.floor(avail/set.size)));}
function buildSopa(){const set=sopaSets[currentSopaSetIdx];const grid=document.getElementById('sopaGrid');grid.innerHTML='';const sz=getSopaCellSize();grid.style.gridTemplateColumns=`repeat(${set.size},${sz}px)`;grid.style.gridTemplateRows=`repeat(${set.size},${sz}px)`;sopaFirstClickCell=null;sopaSelectedCells=[];for(let r=0;r<set.size;r++)for(let c=0;c<set.size;c++){const cell=document.createElement('div');cell.className='sopa-cell';cell.style.width=sz+'px';cell.style.height=sz+'px';cell.style.fontSize=Math.max(11,sz-10)+'px';cell.textContent=set.grid[r][c];cell.dataset.row=r;cell.dataset.col=c;const alreadyFound=set.words.find(w=>sopaFoundWords.has(w.w)&&w.cells.some(([wr,wc])=>wr===r&&wc===c));if(alreadyFound)cell.classList.add('sopa-found');grid.appendChild(cell);}setupSopaEvents();const wl=document.getElementById('sopaWords');wl.innerHTML='';set.words.forEach(wObj=>{const sp=document.createElement('span');sp.className='sopa-w'+(sopaFoundWords.has(wObj.w)?' found':'');sp.id='sw-'+wObj.w;sp.textContent=wObj.w;wl.appendChild(sp);});}
function setupSopaEvents(){const grid=document.getElementById('sopaGrid');grid.onpointerdown=e=>{const cell=e.target.closest('.sopa-cell');if(!cell)return;e.preventDefault();grid.setPointerCapture(e.pointerId);sopaPointerStartCell=cell;sopaPointerMoved=false;cell.classList.add('sopa-sel');sopaSelectedCells=[cell];};grid.onpointermove=e=>{if(!sopaPointerStartCell)return;e.preventDefault();const el=document.elementFromPoint(e.clientX,e.clientY);const cell=el?el.closest('.sopa-cell'):null;if(!cell)return;const sr=parseInt(sopaPointerStartCell.dataset.row),sc=parseInt(sopaPointerStartCell.dataset.col);const er=parseInt(cell.dataset.row),ec=parseInt(cell.dataset.col);if(sr!==er||sc!==ec)sopaPointerMoved=true;document.querySelectorAll('.sopa-cell.sopa-sel').forEach(c=>c.classList.remove('sopa-sel'));sopaSelectedCells=[];getSopaPath(sr,sc,er,ec).forEach(([r,c])=>{const pc=document.querySelector(`#sopaGrid [data-row="${r}"][data-col="${c}"]`);if(pc){pc.classList.add('sopa-sel');sopaSelectedCells.push(pc);}});};grid.onpointerup=e=>{if(!sopaPointerStartCell)return;e.preventDefault();grid.releasePointerCapture(e.pointerId);if(sopaPointerMoved&&sopaSelectedCells.length>1){checkSopaSelection();}else{const cell=sopaPointerStartCell;document.querySelectorAll('.sopa-cell.sopa-sel').forEach(c=>c.classList.remove('sopa-sel'));sopaSelectedCells=[];if(!sopaFirstClickCell){sopaFirstClickCell=cell;cell.classList.add('sopa-start');}else if(sopaFirstClickCell===cell){cell.classList.remove('sopa-start');sopaFirstClickCell=null;}else{const sr=parseInt(sopaFirstClickCell.dataset.row),sc=parseInt(sopaFirstClickCell.dataset.col);const er=parseInt(cell.dataset.row),ec=parseInt(cell.dataset.col);sopaFirstClickCell.classList.remove('sopa-start');sopaFirstClickCell=null;getSopaPath(sr,sc,er,ec).forEach(([r,c])=>{const pc=document.querySelector(`#sopaGrid [data-row="${r}"][data-col="${c}"]`);if(pc){pc.classList.add('sopa-sel');sopaSelectedCells.push(pc);}});checkSopaSelection();}}sopaPointerStartCell=null;sopaPointerMoved=false;};}
function getSopaPath(r1,c1,r2,c2){const dr=Math.sign(r2-r1),dc=Math.sign(c2-c1);const lr=Math.abs(r2-r1),lc=Math.abs(c2-c1);if(lr!==0&&lc!==0&&lr!==lc)return[[r1,c1]];const len=Math.max(lr,lc);const path=[];for(let i=0;i<=len;i++)path.push([r1+dr*i,c1+dc*i]);return path;}
function checkSopaSelection(){const set=sopaSets[currentSopaSetIdx];const word=sopaSelectedCells.map(c=>c.textContent).join('');const wordRev=word.split('').reverse().join('');const found=set.words.find(wObj=>!sopaFoundWords.has(wObj.w)&&(wObj.w===word||wObj.w===wordRev));if(found){sopaFoundWords.add(found.w);found.cells.forEach(([r,c])=>{const cell=document.querySelector(`#sopaGrid [data-row="${r}"][data-col="${c}"]`);if(cell){cell.classList.remove('sopa-sel','sopa-start');cell.classList.add('sopa-found');}});const sp=document.getElementById('sw-'+found.w);if(sp)sp.classList.add('found');if(!xpTracker.sopa.has(found.w)){xpTracker.sopa.add(found.w);pts(1);}sfx('ok');if(sopaFoundWords.size===set.words.length){fin('s-sopa');sfx('fan');showToast('🎉 ¡Todas las palabras encontradas!');}else showToast('✅ ¡Encontraste: '+found.w+'!');}else sfx('no');document.querySelectorAll('.sopa-cell.sopa-sel').forEach(c=>c.classList.remove('sopa-sel'));sopaSelectedCells=[];}
function nextSopaSet(){sfx('click');sopaFoundWords=new Set();currentSopaSetIdx=(currentSopaSetIdx+1)%sopaSets.length;buildSopa();showToast('🔄 Nueva sopa cargada');}
let _sopaResizeTimer=null;
window.addEventListener('resize',()=>{clearTimeout(_sopaResizeTimer);_sopaResizeTimer=setTimeout(()=>{if(document.getElementById('s-sopa').classList.contains('active'))buildSopa();},200);});

