const evalTFBank=[{"q":"La regla de oro de esta materia exige que toda herramienta se cite con autor y año.","a":true},{"q":"Tom Wolfe publicó «The New Journalism» en 1973.","a":true},{"q":"Reordenar e inventar son la misma cosa.","a":false},{"q":"Usar las técnicas de la ficción (Wolfe, 1973) autoriza a fabricar hechos.","a":false},{"q":"Truman Capote publicó «A sangre fría» en 1966.","a":true},{"q":"Las dudas documentadas sobre «A sangre fría» prueban que Capote inventó todo el libro.","a":false},{"q":"Philippe Lejeune describe el pacto autobiográfico en 1975.","a":true},{"q":"Janet Malcolm publicó «El periodista y el asesino» en 1990.","a":true},{"q":"Janet Cooke inventó a Jimmy y ganó el Pulitzer en 1981, que tuvo que devolver.","a":true},{"q":"James Frey vendió como reales unas memorias en gran parte fabricadas, destapado en 2006.","a":true},{"q":"La verdad emocional sostiene el pacto con el lector aunque los hechos sean inventados.","a":false},{"q":"Johnson, Hashtroudi y Lindsay describen el monitoreo de la fuente en 1993.","a":true},{"q":"Según Garry y colegas (1996), imaginar un suceso baja la confianza de que ocurrió.","a":false},{"q":"La ficha de la no ficción tiene tres casillas: si ocurrió, qué se reordenó, y si hay permiso.","a":true},{"q":"Un personaje compuesto se puede publicar sin declararlo, si nadie se da cuenta.","a":false}];
